document.addEventListener('click',function(e){var btn=e.target.closest('[data-bs-toggle="modal"]');if(btn){var target=document.querySelector(btn.getAttribute('data-bs-target'));if(target){target.style.display='block';target.classList.add('show');}}var close=e.target.closest('[data-bs-dismiss="modal"],.btn-close');if(close){var modal=close.closest('.modal');if(modal){modal.classList.remove('show');modal.style.display='none';}}});
